-- Loja → Plano de campanhas (11/10/2026): tabela + 13 campanhas sugeridas
-- até o fim do ano. Todas entram como SUGGESTED (nada liga na loja até o usuário
-- ativar em Loja → Plano de campanhas).
CREATE TABLE "StoreCampaign" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "slug" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "objective" TEXT NOT NULL DEFAULT '',
    "mechanic" TEXT NOT NULL DEFAULT '',
    "startsAt" DATETIME NOT NULL,
    "endsAt" DATETIME NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'SUGGESTED',
    "promoPercent" REAL NOT NULL DEFAULT 0,
    "promoLabel" TEXT NOT NULL DEFAULT '',
    "productSkus" TEXT NOT NULL DEFAULT '[]',
    "coupon" TEXT NOT NULL DEFAULT '',
    "collection" TEXT NOT NULL DEFAULT '',
    "banner" TEXT NOT NULL DEFAULT '',
    "couponId" TEXT,
    "collectionId" TEXT,
    "bannerId" TEXT,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);
CREATE UNIQUE INDEX "StoreCampaign_slug_key" ON "StoreCampaign"("slug");
INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_dia_do_professor','dia-do-professor','Dia do Professor','Aproveitar a data de 15/10 com lembrancinhas baratas que pais e turmas compram em quantidade.','10% nas lembrancinhas de maior margem + coleção na Vitrine + banner.',1791774000000,1792119540000,'SUGGESTED',10,'Dia do Professor','["B.018","B.013","B.004"]','','{"title":"Para professores","lead":"Lembrancinhas para a turma toda","tone":"rosa","skus":["B.018","B.013","D.003","D.005","U.001","B.004"]}','{"title":"Dia do Professor é quinta (15/10)","subtitle":"10% nas ponteiras com o nome de cada aluno","buttonLabel":"Ver lembrancinhas","sku":"B.018","imageIndex":0}',0,CURRENT_TIMESTAMP);
INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_bem_vindo_instagram','bem-vindo-instagram','Bem-vindo do Instagram','Transformar seguidores novos em primeira compra e medir quanto o Instagram vende.','Cupom BEMVINDO10: 10% em pedidos a partir de R$ 60, até 50 usos. Divulgar só no Instagram.',1791860400000,1798772340000,'SUGGESTED',0,'','[]','{"code":"BEMVINDO10","kind":"PERCENT","value":10,"minOrder":60,"maxUses":50}','','',1,CURRENT_TIMESTAMP);
INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_esquenta_natal','esquenta-natal','Esquenta de Natal — decore antes','Puxar as vendas de decoração de Natal para outubro/novembro, antes da fila de produção de dezembro.','Cupom NATAL10: 10% a partir de R$ 80 (o ticket protege a margem das peças de Natal) + coleção + banner da Árvore Japandi.',1792119600000,1794279540000,'SUGGESTED',0,'','[]','{"code":"NATAL10","kind":"PERCENT","value":10,"minOrder":80}','{"title":"Natal na sala","lead":"Decore antes e receba sem correria","tone":"vinho","skus":["D.026","D.018","N.001","D.010","D.002","D.012","D.013","D.014"]}','{"title":"Decore antes, receba sem correria","subtitle":"Cupom NATAL10: 10% acima de R$ 80 na decoração de Natal","buttonLabel":"Ver decoração de Natal","sku":"D.026","imageIndex":0}',2,CURRENT_TIMESTAMP);
INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_lembrancinhas_fim_de_ano','lembrancinhas-fim-de-ano','Lembrancinhas de fim de ano da turma','Encerramento do ano letivo e confraternizações: pedidos grandes de peças baratas.','10% nas lembrancinhas de alta margem + cupom TURMA15 (15% a partir de R$ 150) + coleção. Soma com o desconto por quantidade da loja.',1792465200000,1796525940000,'SUGGESTED',10,'Fim de ano','["B.018","B.004","B.011","B.017","B.013"]','{"code":"TURMA15","kind":"PERCENT","value":15,"minOrder":150}','{"title":"Lembrancinhas da turma","lead":"Para o encerramento do ano letivo","tone":"oliva","skus":["B.018","B.004","B.005","B.011","B.017","B.015","B.013","B.007"]}','',3,CURRENT_TIMESTAMP);
INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_brindes_empresas','brindes-empresas','Brindes de fim de ano para empresas','Vender kits com logo e chaveiros para empresas, que compram em volume e com antecedência.','Cupom EMPRESA10: 10% a partir de R$ 300 + coleção de brindes + banner do kit com logo.',1793502000000,1797130740000,'SUGGESTED',0,'','[]','{"code":"EMPRESA10","kind":"PERCENT","value":10,"minOrder":300}','{"title":"Brindes de fim de ano","lead":"Para clientes e equipe — com a sua marca","tone":"vinho","skus":["B.008","B.018","U.001","B.004","A.001","B.013"]}','{"title":"Brindes de fim de ano com a sua marca","subtitle":"Cupom EMPRESA10: 10% acima de R$ 300","buttonLabel":"Ver brindes","sku":"B.008","imageIndex":0}',4,CURRENT_TIMESTAMP);
