INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_natal_com_jesus','natal-com-jesus','Natal com Jesus — presentes de fé','Público cristão: lembrar o sentido do Natal com o presépio e o Mini Jesus.','5% nas peças de fé + coleção + banner do Presépio.',1796094000000,1798167540000,'SUGGESTED',5,'Natal com Jesus','["B.009","B.006","D.014","D.015"]','','{"title":"Natal com Jesus","lead":"O verdadeiro sentido do Natal","tone":"oliva","skus":["D.014","B.009","B.006","D.015","D.003"]}','{"title":"O verdadeiro sentido do Natal","subtitle":"Presépio e Mini Jesus com 5% até a véspera","buttonLabel":"Ver presentes de fé","sku":"D.014","imageIndex":0}',10,CURRENT_TIMESTAMP);
