INSERT INTO "StoreCampaign" ("id","slug","title","objective","mechanic","startsAt","endsAt","status","promoPercent","promoLabel","productSkus","coupon","collection","banner","sortOrder","updatedAt") VALUES ('camp_ano_novo_organizado','ano-novo-organizado','Ano novo organizado','Aproveitar a semana entre Natal e Ano Novo (metas, organização da casa) para não zerar as vendas.','10% em organização e no Checklist de tarefas + coleção.',1798254000000,1798772340000,'SUGGESTED',10,'Ano novo organizado','["D.001","D.006","A.001","B.010"]','','{"title":"2027 organizado","lead":"Comece o ano com a casa em ordem","tone":"oliva","skus":["B.010","D.001","D.006","A.001","D.005","D.007"]}','',12,CURRENT_TIMESTAMP);
